$ErrorActionPreference='Stop';$root=$PSScriptRoot;$lock='D:\DLSSNR-Lab\gpu.lock';$hip='DLSS5-AMD\native-game-tiled-assets\HIP';$exact='D:\DLSSNR-Lab\fast-tier\exact';$games=@('C:\Program Files (x86)\Steam\steamapps\common\StellarBlade\SB\Binaries\Win64','C:\XboxGames\Onimusha- Way of the Sword\Content')
function Idle {& 'D:\DLSSNR-Lab\game-check.ps1' Stellar Onimusha Magpie Forza Cyberpunk;if($LASTEXITCODE -ne 1){throw 'game active'}}
Idle;$f=[IO.File]::Open($lock,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::Read);$f.Close()
try{$b="$root\backups\$(Get-Date -Format yyyyMMdd-HHmmss)";New-Item -ItemType Directory -Force $b|Out-Null;$cfg=@{};foreach($i in 0,1){$g=$games[$i];New-Item -ItemType Directory -Force "$b\game-$i\gfx1200","$b\game-$i\gfx1201"|Out-Null;foreach($a in 'gfx1200','gfx1201'){Copy-Item "$g\$hip\$a\c512-m32-deep.hsaco" "$b\game-$i\$a\c512-m32-deep.hsaco"};Copy-Item "$g\$hip\SHA256SUMS" "$b\game-$i\SHA256SUMS";foreach($n in 'default-config.txt','custom-config.txt','native-game-flags.txt'){$cfg["$i-$n"]=(Get-FileHash "$g\DLSS5-AMD\$n").Hash};foreach($n in 'dlss5-amd.addon64','LmxxfNrRuntime.dll','_storage_\LmxxfNrRuntime.dll'){if(Test-Path "$g\$n"){$cfg["$i-$n"]=(Get-FileHash "$g\$n").Hash}}};Copy-Item $exact "$b\exact" -Recurse
$rollback=@();foreach($i in 0,1){foreach($a in 'gfx1200','gfx1201'){$rollback+="Copy-Item '$b\game-$i\$a\c512-m32-deep.hsaco' '$($games[$i])\$hip\$a\c512-m32-deep.hsaco' -Force"};$rollback+="Copy-Item '$b\game-$i\SHA256SUMS' '$($games[$i])\$hip\SHA256SUMS' -Force"};$rollback+="Copy-Item '$b\exact\*' '$exact' -Recurse -Force";[IO.File]::WriteAllLines("$b\rollback.ps1",$rollback)
try{foreach($i in 0,1){Idle;$g=$games[$i];foreach($a in 'gfx1200','gfx1201'){Copy-Item "$root\HIP\$a\c512-m32-deep.hsaco" "$g\$hip\$a\c512-m32-deep.hsaco" -Force;if((Get-FileHash "$root\HIP\$a\c512-m32-deep.hsaco").Hash -ne (Get-FileHash "$g\$hip\$a\c512-m32-deep.hsaco").Hash){throw 'module readback'}};$lines=@(Get-ChildItem "$g\$hip" -Recurse -Filter '*.hsaco'|Sort-Object FullName|%{"$((Get-FileHash $_.FullName).Hash.ToLower())  $($_.FullName.Substring(("$g\$hip\").Length).Replace('\','/'))"});if($lines.Count -ne 76){throw 'module count'};[IO.File]::WriteAllLines("$g\$hip\SHA256SUMS",$lines);foreach($n in 'default-config.txt','custom-config.txt','native-game-flags.txt'){if($cfg["$i-$n"] -ne (Get-FileHash "$g\DLSS5-AMD\$n").Hash){throw 'config changed'}};foreach($n in 'dlss5-amd.addon64','LmxxfNrRuntime.dll','_storage_\LmxxfNrRuntime.dll'){if($cfg.ContainsKey("$i-$n") -and $cfg["$i-$n"] -ne (Get-FileHash "$g\$n").Hash){throw 'host binary changed'}}}
foreach($a in 'gfx1200','gfx1201'){Copy-Item "$root\HIP\$a\c512-m32-deep.hsaco" "$exact\$a\c512-m32-deep.hsaco" -Force};foreach($i in 0,1){$n=if($i){'oni'}else{'stellar'};Copy-Item "$($games[$i])\$hip\SHA256SUMS" "$exact\$n-SHA256SUMS" -Force};if((Get-FileHash "$($games[0])\$hip\SHA256SUMS").Hash -ne (Get-FileHash "$($games[1])\$hip\SHA256SUMS").Hash){throw 'SUMS mismatch'}
}catch{& "$b\rollback.ps1";throw}
"INSTALLED SUMS=$((Get-FileHash "$($games[0])\$hip\SHA256SUMS").Hash) BACKUP=$b CONFIG_HOST_UNCHANGED=1"
}finally{Remove-Item $lock -Force}
